//! Story clues that appear as the campaign reveals them.
//!
//! Each step is hidden until the server reports the flag that unlocks it
//! (`state/dm_journal.rs`, `docs/specs/dm-flag-channel.md`). The client never
//! decides a clue is earned from chat or its own actions: no flag report, no
//! clue. Generated by `Hercules/tools/gen-hunts.py`; do not edit by hand.

use std::sync::OnceLock;

const STORY_STEPS: &str = include_str!("hunt_story.tsv");

/// What unlocks a step.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RevealCondition {
    /// `always`: visible without any flag.
    Always,
    /// `name`: the flag is non-zero.
    Flag(String),
    /// `name:N`: bit mask `N` is set in the flag.
    Bits(String, i64),
}

impl RevealCondition {
    fn parse(text: &str) -> Option<Self> {
        let text = text.trim();
        if text == "always" {
            return Some(Self::Always);
        }
        match text.split_once(':') {
            None if is_flag_name(text) => Some(Self::Flag(text.to_owned())),
            Some((name, mask)) if is_flag_name(name) => {
                let mask: i64 = mask.trim().parse().ok()?;
                (mask > 0).then(|| Self::Bits(name.to_owned(), mask))
            }
            _ => None,
        }
    }

    /// Whether the flag values from `flag` satisfy the condition.
    pub fn holds(&self, flag: impl Fn(&str) -> i64) -> bool {
        match self {
            Self::Always => true,
            Self::Flag(name) => flag(name) != 0,
            Self::Bits(name, mask) => flag(name) & mask != 0,
        }
    }
}

/// One clue in an investigation.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StoryStep {
    pub id: String,
    pub speaker: String,
    pub clue: String,
    pub remaining_action: String,
    pub reveal: RevealCondition,
}

/// Every step, in the order the table lists them.
pub fn story_steps() -> &'static [StoryStep] {
    static STEPS: OnceLock<Vec<StoryStep>> = OnceLock::new();
    STEPS.get_or_init(|| parse_story_steps(STORY_STEPS))
}

/// The steps whose reveal condition the server's reported flags satisfy.
pub fn visible_story_steps(flag: impl Fn(&str) -> i64) -> Vec<&'static StoryStep> {
    story_steps().iter().filter(|step| step.reveal.holds(&flag)).collect()
}

fn is_flag_name(name: &str) -> bool {
    !name.is_empty()
        && name
            .bytes()
            .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'_')
}

fn parse_story_steps(data: &str) -> Vec<StoryStep> {
    let mut steps = Vec::new();

    for line in data.lines() {
        let line = line.trim_end();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }

        // id, speaker, clue, remaining action, next lead, visibility, reveal condition
        let fields: Vec<&str> = line.split('\t').collect();
        let [id, speaker, clue, remaining_action, _next_lead, _visibility, reveal] = fields[..] else {
            continue;
        };
        let Some(reveal) = RevealCondition::parse(reveal) else {
            continue;
        };
        if id.trim().is_empty() || clue.trim().is_empty() {
            continue;
        }

        steps.push(StoryStep {
            id: id.trim().to_owned(),
            speaker: speaker.trim().to_owned(),
            clue: clue.trim().to_owned(),
            remaining_action: remaining_action.trim().to_owned(),
            reveal,
        });
    }

    steps
}

#[cfg(test)]
mod tests {
    use super::{RevealCondition, parse_story_steps, story_steps, visible_story_steps};

    fn flags(pairs: &'static [(&'static str, i64)]) -> impl Fn(&str) -> i64 {
        move |name| pairs.iter().find(|(key, _)| *key == name).map_or(0, |(_, value)| *value)
    }

    fn ids(steps: Vec<&super::StoryStep>) -> Vec<&str> {
        steps.into_iter().map(|step| step.id.as_str()).collect()
    }

    #[test]
    fn the_bundled_table_parses_every_arc_one_step() {
        assert_eq!(story_steps().len(), 8);
    }

    #[test]
    fn nothing_is_visible_until_the_server_reports_a_flag() {
        assert!(visible_story_steps(flags(&[])).is_empty());
    }

    /// `dm_arc01_clue_mask` bit 1 is the painted sluice and bit 4 is Tibbets;
    /// bit 2 (the child) must not reveal either of them.
    #[test]
    fn a_bit_mask_condition_reveals_only_its_own_bit() {
        assert!(ids(visible_story_steps(flags(&[("dm_arc01_clue_mask", 2)]))).is_empty());
        assert_eq!(ids(visible_story_steps(flags(&[("dm_arc01_clue_mask", 1)]))), ["sluice"]);
        assert_eq!(ids(visible_story_steps(flags(&[("dm_arc01_clue_mask", 5)]))), [
            "sluice", "tibbets"
        ]);
    }

    /// `dm_arc01_holt_approach` takes the values 1 to 3, so any non-zero value
    /// reveals it.
    #[test]
    fn a_plain_flag_is_revealed_by_any_non_zero_value() {
        for value in [1, 2, 3] {
            let pairs: &'static [(&str, i64)] = Box::leak(Box::new([("dm_arc01_holt_approach", value)]));
            assert_eq!(ids(visible_story_steps(flags(pairs))), ["holt"]);
        }
    }

    #[test]
    fn a_started_investigation_shows_the_first_clue_only() {
        assert_eq!(ids(visible_story_steps(flags(&[("dm_arc01_started", 1)]))), ["wynne_start"]);
    }

    #[test]
    fn the_child_flag_reveals_the_mother_and_mira_together() {
        assert_eq!(ids(visible_story_steps(flags(&[("dm_arc01_child_found", 1)]))), [
            "mother", "mira"
        ]);
    }

    #[test]
    fn reveal_conditions_parse_both_forms_and_refuse_the_rest() {
        assert_eq!(RevealCondition::parse("dm_a"), Some(RevealCondition::Flag("dm_a".to_owned())));
        assert_eq!(
            RevealCondition::parse("dm_a:4"),
            Some(RevealCondition::Bits("dm_a".to_owned(), 4))
        );
        assert_eq!(RevealCondition::parse("always"), Some(RevealCondition::Always));
        assert!(RevealCondition::Always.holds(|_| 0));
        for bad in ["", "Dm A", "dm_a:0", "dm_a:-1", "dm_a:x", ":4"] {
            assert_eq!(RevealCondition::parse(bad), None, "{bad:?}");
        }
    }

    #[test]
    fn a_malformed_row_is_dropped_not_fatal() {
        let steps =
            parse_story_steps("# schema=1\nok\tSpeaker\tA clue.\tDo it.\t\thidden\tdm_a\nshort\trow\nbad\tS\tC\tA\t\thidden\tNot A Flag\n");
        assert_eq!(steps.len(), 1);
        assert_eq!(steps[0].id, "ok");
    }
}
